/* ---- src/tree.js ---- */

/**
 * tree.js — tree helpers over the ARTICLES-by-id map: ancestors, top-level
 * categories, a flat sorted index, and a lazy-expansion window for
 * virtualised rendering (model decision #3 — must stay usable at 155
 * articles and on mobile). No DOM here (SR-1); ui.js owns rendering.
 */

function byIdNumeric(a, b) {
  const pa = a.id.split(".").map(Number);
  const pb = b.id.split(".").map(Number);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d !== 0) return d;
  }
  return 0;
}

/** getAncestors(articlesById, id) -> Article[] root-first, excluding id itself. */
function getAncestors(articlesById, id) {
  const chain = [];
  let current = articlesById[id];
  while (current && current.parent && articlesById[current.parent]) {
    current = articlesById[current.parent];
    chain.unshift(current);
  }
  return chain;
}

/** getTopLevel(articlesById) -> Article[] with no parent, id-sorted. */
function getTopLevel(articlesById) {
  return Object.values(articlesById)
    .filter((a) => !a.parent)
    .sort(byIdNumeric);
}

/** flatIndex(articlesById) -> every Article, id-sorted (backs the "All" page). */
function flatIndex(articlesById) {
  return Object.values(articlesById).sort(byIdNumeric);
}

function getChildren(articlesById, id) {
  const article = articlesById[id];
  if (!article || !article.children) return [];
  return article.children.map((cid) => articlesById[cid]).filter(Boolean).sort(byIdNumeric);
}

/**
 * visibleNodes(articlesById, expandedIds) -> Article[]
 * Lazy-expansion tree window: only top-level nodes plus the children of
 * any id present in `expandedIds` are returned, in display order, each
 * tagged with its `depth`. A 155-article cartridge renders a handful of
 * DOM nodes at rest instead of the whole tree; expanding a node reveals
 * only its direct children (themselves collapsed), so a depth-4 tree
 * never renders more than the path the user actually opened.
 */
function visibleNodes(articlesById, expandedIds) {
  const out = [];
  function walk(list, depth) {
    for (const a of list) {
      out.push({ article: a, depth, hasChildren: (a.children || []).length > 0 });
      if ((a.children || []).length > 0 && expandedIds.has(a.id)) {
        walk(getChildren(articlesById, a.id), depth + 1);
      }
    }
  }
  walk(getTopLevel(articlesById), 0);
  return out;
}



/* ---- src/autolink.js ---- */

/**
 * autolink.js — prose cross-linking with a generic-title exclusion list
 * and a title-collision rule (model decision #4, CONTENT-FIT-REPORT.md
 * §4). buildLinkCatalogue() is scoped to whatever ARTICLES map it is
 * given — normally one cartridge's worth, since the shell mounts one
 * MiniWiki instance per cartridge build (model decision #5's per-
 * cartridge extractor output). The collision rule below covers the case
 * where a host ever merges more than one cartridge's articles into a
 * single lookup.
 */

// Verbatim from CONTENT-FIT-REPORT.md §4's exclusion list, lower-cased for
// case-insensitive matching.
const EXCLUDED_TITLES = new Set(
  [
    "style",
    "example",
    "examples",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "forty",
    "one thousand",
  ].map((t) => t.toLowerCase())
);

/** isExcludedTitle(title) -> true if this title must never be auto-linked. */
function isExcludedTitle(title) {
  if (typeof title !== "string") return true;
  const lower = title.trim().toLowerCase();
  if (EXCLUDED_TITLES.has(lower)) return true;
  // Generic heuristic (report §4/§8-#7's "Tropes & symbols: all single-word
  // titles in sections 5–7"): a bare single word of 4 characters or fewer
  // is too likely to appear in ordinary prose to link safely.
  if (!/\s/.test(lower) && lower.length <= 4) return true;
  return false;
}

/**
 * buildLinkCatalogue(articlesById) -> [{id, title}], longest title first.
 *
 * COLLISION RULE: if two different ids share the same (case-insensitive)
 * title, the FIRST one encountered (object key iteration order) wins and
 * every later duplicate is excluded from the catalogue entirely — a
 * mention of that title is never auto-linked to either article, rather
 * than risk silently sending the reader to the wrong one.
 */
function buildLinkCatalogue(articlesById) {
  const firstSeenId = new Map(); // lowercase title -> id
  const collided = new Set();
  for (const [id, article] of Object.entries(articlesById)) {
    if (!article || typeof article.title !== "string") continue;
    const key = article.title.trim().toLowerCase();
    if (!key) continue;
    if (firstSeenId.has(key)) {
      collided.add(key);
      continue;
    }
    firstSeenId.set(key, id);
  }
  const entries = [];
  for (const [title, id] of firstSeenId) {
    if (collided.has(title)) continue;
    if (isExcludedTitle(articlesById[id].title)) continue;
    entries.push({ id, title: articlesById[id].title });
  }
  entries.sort((a, b) => b.title.length - a.title.length);
  return entries;
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * autolinkHtml(html, catalogue, selfId) -> html with the first
 * whole-word, case-insensitive occurrence of each OTHER article's title
 * wrapped in a `.wikilink` anchor. Operates on already-escaped HTML by
 * only rewriting the text runs between tags, so it never mangles markup.
 */
function autolinkHtml(html, catalogue, selfId) {
  if (typeof html !== "string" || html.length === 0) return html;
  const linked = new Set();
  const tagRe = /<[^>]*>/g;
  let lastIndex = 0;
  let match;
  const segments = [];
  while ((match = tagRe.exec(html)) !== null) {
    segments.push({ text: html.slice(lastIndex, match.index), tag: match[0] });
    lastIndex = tagRe.lastIndex;
  }
  segments.push({ text: html.slice(lastIndex), tag: "" });

  let result = "";
  for (const seg of segments) {
    let text = seg.text;
    for (const { id, title } of catalogue) {
      if (id === selfId) continue;
      const key = title.toLowerCase();
      if (linked.has(key)) continue;
      const re = new RegExp(`\\b${escapeRegExp(title)}\\b`, "i");
      const m = text.match(re);
      if (m) {
        text = text.replace(re, `<a class="wikilink" href="#/${id}" data-article-id="${id}">${m[0]}</a>`);
        linked.add(key);
      }
    }
    result += text + seg.tag;
  }
  return result;
}



/* ---- src/search-terms.js ---- */

/**
 * search-terms.js — deterministic "key search terms" generation
 * (requirement 9). NOT an LLM at runtime: a fixed, reproducible scoring
 * pass over the article's own title, ancestor titles, and distinctive
 * body words, minus STOPWORDS. Same input -> same output, every time
 * (asserted by tests/test-search-terms.mjs).
 */

const STOPWORDS = new Set(
  (
    "a an the of and or but if then else for to in on at by with from as is " +
    "are was were be been being this that these those it its into onto over " +
    "under not no nor so than too very can will would should could may might " +
    "must shall do does did have has had which who whom whose what when " +
    "where why how also such each other some any all both more most own " +
    "same per via"
  ).split(/\s+/)
);

function tokenizeWords(text) {
  if (!text) return [];
  return text.match(/[A-Za-z][A-Za-z'-]*/g) || [];
}

/** A capitalised token is a candidate proper noun / technical term. */
function isCapitalisedTechnical(word) {
  return /^[A-Z]/.test(word) && word.length > 1;
}

/**
 * generateSearchTerms(article, ancestors, limit = 10) -> string[]
 * Weighted term set: title words (weight 3) > ancestor-title words
 * (weight 2) > capitalised/technical body words (weight 1). Deduplicated,
 * stopworded, sorted by weight desc then alphabetically for a stable
 * order across runs.
 */
function generateSearchTerms(article, ancestors = [], limit = 10) {
  const scores = new Map();
  const display = new Map();

  function add(word, weight) {
    const key = word.toLowerCase();
    if (key.length < 3 || STOPWORDS.has(key)) return;
    const prior = scores.get(key) || 0;
    scores.set(key, Math.max(prior, weight));
    if (!display.has(key)) display.set(key, word);
  }

  tokenizeWords(article.title).forEach((w) => add(w, 3));
  ancestors.forEach((a) => tokenizeWords(a.title).forEach((w) => add(w, 2)));

  const bodySource = [
    article.lead || "",
    (article.characteristics || []).join(" "),
    (article.examples || []).join(" "),
  ].join(" ");
  tokenizeWords(bodySource).forEach((w) => {
    if (isCapitalisedTechnical(w)) add(w, 1);
  });

  return [...scores.keys()]
    .sort((a, b) => {
      const diff = scores.get(b) - scores.get(a);
      return diff !== 0 ? diff : a < b ? -1 : a > b ? 1 : 0;
    })
    .slice(0, limit)
    .map((key) => display.get(key) || key);
}



/* ---- src/references.js ---- */

/**
 * references.js — MLA-style reference formatting (requirement 8), per
 * System/Templates/Template_MLA_Reference.md. Source data is ONLY the
 * extractor's `article.references` (build/extract_articles.py's
 * build_reference(), sourced from the content file's YAML frontmatter
 * `title:` / `description:` / `provenance:` fields) — this module never
 * invents a citation. An article with no `references` yields an empty
 * list; ui.js omits the section entirely rather than render an empty
 * heading.
 */

/**
 * formatMlaReference(ref) -> string
 * ref: {title, container, note} — the shape build_reference() emits.
 * Rendered as an MLA-style entry: the content file's own declared title,
 * its container/description, then any further provenance note — never a
 * fabricated author, date, or publisher beyond what frontmatter states.
 */
function formatMlaReference(ref) {
  if (!ref || !ref.title) return "";
  const sentence = (text) => text.trim().replace(/\.?$/, ".");
  const parts = [sentence(ref.title)];
  if (ref.container) parts.push(sentence(ref.container));
  if (ref.note && ref.note !== ref.container) parts.push(sentence(ref.note));
  return parts.join(" ");
}

/** formatReferences(article) -> string[] (never throws on a missing field). */
function formatReferences(article) {
  const refs = article && article.references;
  if (!Array.isArray(refs) || refs.length === 0) return [];
  return refs.map(formatMlaReference).filter(Boolean);
}



/* ---- src/clipboard.js ---- */

/**
 * clipboard.js — copy-to-clipboard for the "key search terms" box
 * (requirement 9), offline-first: navigator.clipboard.writeText when
 * available, falling back to a hidden textarea + document.execCommand
 * ("copy") when it is not (older Safari, or a clipboard-permission-
 * denied file:// context). Never throws (JS-2): callers get a resolved
 * boolean, not a rejected promise, even when the fallback also fails.
 */

function legacyCopy(text, doc) {
  if (!doc || !doc.createElement) {
    console.warn("clipboard.legacyCopy: no document available for the execCommand fallback");
    return false;
  }
  const textarea = doc.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  doc.body.appendChild(textarea);
  textarea.select();
  let ok = false;
  try {
    ok = doc.execCommand ? doc.execCommand("copy") : false;
  } catch (e) {
    console.warn("clipboard.legacyCopy: execCommand fallback threw", e);
    ok = false;
  }
  doc.body.removeChild(textarea);
  return ok;
}

/** copyToClipboard(text, doc?) -> Promise<boolean> */
function copyToClipboard(text, doc) {
  const d = doc || (typeof document !== "undefined" ? document : undefined);
  if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text).then(
      () => true,
      () => legacyCopy(text, d)
    );
  }
  return Promise.resolve(legacyCopy(text, d));
}



/* ---- src/markdown.js ---- */

/**
 * markdown.js — the tiny amount of markdown rendering MiniWiki needs at
 * RUNTIME (the build-time extractor does its own paragraph-only render
 * into body_html already; this file exists for the module's public
 * renderBody() escape hatch when a host passes raw markdown directly,
 * e.g. from a future non-extractor content source). One job (SR-1):
 * escape untrusted text, then apply a handful of inline markers.
 */

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** renderInline(text) -> escaped HTML with bold/italic markers applied. */
function renderInline(text) {
  const escaped = escapeHtml(text);
  return escaped
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>");
}

/** renderParagraphs(text) -> one <p> per blank-line-separated block. */
function renderParagraphs(text) {
  if (typeof text !== "string" || text.trim().length === 0) return "";
  return text
    .split(/\n\s*\n/)
    .map((block) => block.trim())
    .filter(Boolean)
    .map((block) => `<p>${renderInline(block)}</p>`)
    .join("");
}



